import { describe, it, expect } from 'vitest';
import { validateTodoInput } from '../src/todo';

describe('validateTodoInput', () => {
  it('rejects empty title', () => {
    expect(validateTodoInput({ title: '', description: '' })).toBe(false);
  });

  it('rejects whitespace-only title', () => {
    expect(validateTodoInput({ title: '   ', description: '' })).toBe(false);
  });

  it('rejects title longer than 200 characters', () => {
    expect(validateTodoInput({ title: 'a'.repeat(201), description: '' })).toBe(false);
  });

  it('accepts title exactly 200 characters', () => {
    expect(validateTodoInput({ title: 'a'.repeat(200), description: '' })).toBe(true);
  });

  it('rejects description longer than 1000 characters', () => {
    expect(validateTodoInput({ title: 'Valid', description: 'a'.repeat(1001) })).toBe(false);
  });

  it('accepts description exactly 1000 characters', () => {
    expect(validateTodoInput({ title: 'Valid', description: 'a'.repeat(1000) })).toBe(true);
  });

  it('accepts valid input with description', () => {
    expect(validateTodoInput({ title: 'Buy milk', description: 'From the store' })).toBe(true);
  });

  it('accepts valid input without description', () => {
    expect(validateTodoInput({ title: 'Buy milk', description: '' })).toBe(true);
  });
});

describe('sanitizeInput', () => {
  it('escapes < to &lt;', () => {
    expect(sanitizeInput('<script>')).toBe('&lt;script&gt;');
  });

  it('escapes > to &gt;', () => {
    expect(sanitizeInput('x > y')).toBe('x &gt; y');
  });

  it('escapes double quotes to &quot;', () => {
    expect(sanitizeInput('Say "hello"')).toBe('Say &quot;hello&quot;');
  });

  it('escapes single quotes to &#039;', () => {
    expect(sanitizeInput("It's")).toBe('It&#039;s');
  });

  it('escapes multiple dangerous characters in one string', () => {
    expect(sanitizeInput('<img src="x" onerror=\'alert(1)\'>')).toBe('&lt;img src=&quot;x&quot; onerror=&#039;alert(1)&#039;&gt;');
  });

  it('returns unchanged string with no dangerous characters', () => {
    expect(sanitizeInput('Hello world')).toBe('Hello world');
  });
});

import { vi } from 'vitest';
import { createTodo } from '../src/todo';
import { db } from '../src/database';

vi.mock('../src/database', () => ({ db: { query: vi.fn() } }));

describe('createTodo', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('throws error when validation fails', async () => {
    await expect(createTodo({ title: '', description: '' })).rejects.toThrow('Invalid todo input');
  });

  it('sanitizes title and description before saving', async () => {
    await createTodo({ title: '<script>alert(1)</script>', description: 'Test "quote"' });
    const callArgs = (db.query as any).mock.calls[0];
    expect(callArgs[1][1]).toBe('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(callArgs[1][2]).toBe('Test &quot;quote&quot;');
  });

  it('trims title whitespace', async () => {
    await createTodo({ title: '  Task  ', description: '' });
    const callArgs = (db.query as any).mock.calls[0];
    expect(callArgs[1][1]).toBe('Task');
  });

  it('uses parameterized query to prevent SQL injection', async () => {
    await createTodo({ title: 'Valid', description: 'Desc' });
    const callArgs = (db.query as any).mock.calls[0];
    expect(callArgs[0]).toContain('$1');
    expect(callArgs[0]).toContain('$2');
    expect(callArgs[1]).toHaveLength(5);
  });

  it('generates a unique ID and sets completed to false', async () => {
    const result = await createTodo({ title: 'Task', description: '' });
    expect(result.id).toMatch(/^todo_\d+_[a-z0-9]+$/);
    expect(result.completed).toBe(false);
    expect(result.createdAt).toBeInstanceOf(Date);
  });
});

it('handles undefined description gracefully', async () => {
  const result = await createTodo({ title: 'Task', description: undefined as any });
  expect(result.description).toBe('');
});

describe('getAllTodos', () => {
  it('executes query with ORDER BY created_at DESC', async () => {
    (db.query as any).mockResolvedValue([{ id: '1', title: 'Task', completed: false }]);
    await getAllTodos();
    expect(db.query).toHaveBeenCalledWith('SELECT * FROM todos ORDER BY created_at DESC');
  });

  it('returns array of todos from database', async () => {
    const mockTodos = [{ id: '1', title: 'Task 1' }, { id: '2', title: 'Task 2' }];
    (db.query as any).mockResolvedValue(mockTodos);
    const result = await getAllTodos();
    expect(result).toEqual(mockTodos);
  });
});

describe('getTodoById', () => {
  it('returns todo when found', async () => {
    const mockTodo = { id: '123', title: 'Task', completed: false };
    (db.query as any).mockResolvedValue([mockTodo]);
    const result = await getTodoById('123');
    expect(result).toEqual(mockTodo);
    expect(db.query).toHaveBeenCalledWith('SELECT * FROM todos WHERE id = $1', ['123']);
  });

  it('returns null when todo not found', async () => {
    (db.query as any).mockResolvedValue([]);
    const result = await getTodoById('nonexistent');
    expect(result).toBeNull();
  });
});

it('returns null when rows array is empty', async () => {
  (db.query as any).mockResolvedValue([]);
  expect(await getTodoById('missing')).toBeNull();
});

describe('updateTodoStatus', () => {
  it('executes UPDATE with parameterized query', async () => {
    await updateTodoStatus('todo123', true);
    expect(db.query).toHaveBeenCalledWith('UPDATE todos SET completed = $1 WHERE id = $2', [true, 'todo123']);
  });

  it('updates status to false', async () => {
    await updateTodoStatus('todo456', false);
    expect(db.query).toHaveBeenCalledWith(expect.any(String), [false, 'todo456']);
  });
});

describe('deleteTodo', () => {
  it('executes DELETE with parameterized query', async () => {
    await deleteTodo('todo789');
    expect(db.query).toHaveBeenCalledWith('DELETE FROM todos WHERE id = $1', ['todo789']);
  });
});

describe('searchTodos (VULNERABLE)', () => {
  it('executes search query with keyword interpolated directly (SQL injection risk)', async () => {
    await searchTodos('test');
    const callArgs = (db.query as any).mock.calls[0];
    expect(callArgs[0]).toContain("%test%");
    expect(callArgs[0]).not.toContain('$1');
  });

  it('is vulnerable to SQL injection attack', async () => {
    // This test documents the vulnerability - DO NOT REMOVE until fixed
    const maliciousInput = "test' OR '1'='1";
    await searchTodos(maliciousInput);
    const callArgs = (db.query as any).mock.calls[0];
    expect(callArgs[0]).toContain(maliciousInput);
    // Query would be: SELECT * FROM todos WHERE title LIKE '%test' OR '1'='1%' ...
    // This bypasses the LIKE condition and returns all rows
  });
});

describe('searchTodosByStatus (VULNERABLE)', () => {
  it('concatenates completed parameter directly into query (SQL injection risk)', async () => {
    await searchTodosByStatus('true');
    const callArgs = (db.query as any).mock.calls[0];
    expect(callArgs[0]).toContain('= true');
    expect(callArgs[0]).not.toContain('$1');
