    await searchTodosByStatus(maliciousInput);
    const callArgs = (db.query as any).mock.calls[0];
    expect(callArgs[0]).toContain(maliciousInput);
    // Query would execute: SELECT * FROM todos WHERE completed = 1 OR 1=1; DROP TABLE todos;--
